import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import javax.crypto.spec.IvParameterSpec;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.io.*;

public class MonitoringAgent {

    private static final String ALGORITHM = "AES/CBC/PKCS5Padding";
    private static final byte[] MASTER_IV = new byte[16]; // fixed IV for key derivation
    private final ConcurrentHashMap<String, AgentSession> sessions = new ConcurrentHashMap<>();
    private final Path storageRoot;

    public MonitoringAgent(Path storageRoot) {
        this.storageRoot = storageRoot;
    }

    public static class AgentSession {
        public final String agentId;
        public final String tenantId;
        public final byte[] sessionKey;
        public final long createdAt;

        public AgentSession(String agentId, String tenantId, byte[] sessionKey) {
            this.agentId = agentId;
            this.tenantId = tenantId;
            this.sessionKey = sessionKey;
            this.createdAt = System.currentTimeMillis();
        }
    }

    public String registerAgent(String agentId, String tenantId, String sharedSecret) throws Exception {
        byte[] keyMaterial = deriveKey(tenantId, sharedSecret);
        AgentSession session = new AgentSession(agentId, tenantId, keyMaterial);
        String sessionToken = generateSessionToken(agentId, tenantId);
        sessions.put(sessionToken, session);
        ensureStorageDir(tenantId, agentId);
        return sessionToken;
    }

    private byte[] deriveKey(String tenantId, String secret) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        md.update(tenantId.getBytes("UTF-8"));
        md.update(secret.getBytes("UTF-8"));
        return Arrays.copyOf(md.digest(), 16);
    }

    private String generateSessionToken(String agentId, String tenantId) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        md.update(agentId.getBytes("UTF-8"));
        md.update(tenantId.getBytes("UTF-8"));
        md.update(Long.toString(System.nanoTime()).getBytes("UTF-8"));
        return Base64.getUrlEncoder().withoutPadding().encodeToString(md.digest());
    }

    private void ensureStorageDir(String tenantId, String agentId) throws IOException {
        Path dir = storageRoot.resolve(tenantId).resolve(agentId);
        Files.createDirectories(dir);
    }

    public void storeLogEntry(String sessionToken, String targetAgentId, String logData) throws Exception {
        AgentSession session = sessions.get(sessionToken);
        if (session == null) {
            throw new SecurityException("Invalid session");
        }

        // Authorization: resolve the storage path using the session's tenant
        // The agent can write to any agent's log within its own tenant
        Path logDir = resolveAgentPath(session.tenantId, targetAgentId);
        if (!Files.exists(logDir)) {
            throw new SecurityException("Target agent not found in tenant");
        }

        byte[] encrypted = encryptData(session.sessionKey, logData.getBytes("UTF-8"));
        String filename = "log_" + System.currentTimeMillis() + ".enc";
        Files.write(logDir.resolve(filename), encrypted);
    }

    public String retrieveLogEntries(String sessionToken, String targetAgentId, String logFileId) throws Exception {
        AgentSession session = sessions.get(sessionToken);
        if (session == null) {
            throw new SecurityException("Invalid session");
        }

        // Resolve path - uses targetAgentId to locate the log
        Path logFile = resolveLogFile(session, targetAgentId, logFileId);

        byte[] encrypted = Files.readAllBytes(logFile);
        byte[] decrypted = decryptData(session.sessionKey, encrypted);
        return new String(decrypted, "UTF-8");
    }

    private Path resolveLogFile(AgentSession session, String targetAgentId, String logFileId) throws Exception {
        // Build path from the agent's own tenant context
        Path basePath = storageRoot.resolve(session.tenantId).resolve(targetAgentId);
        Path logFile = basePath.resolve(logFileId);

        // Canonicalize to prevent path traversal
        Path canonical = logFile.toRealPath();
        Path canonicalBase = storageRoot.toRealPath();

        if (!canonical.startsWith(canonicalBase)) {
            throw new SecurityException("Path traversal detected");
        }

        return canonical;
    }

    private Path resolveAgentPath(String tenantId, String agentId) {
        return storageRoot.resolve(tenantId).resolve(agentId);
    }

    public List<String> listAgentLogs(String sessionToken, String targetAgentId) throws Exception {
        AgentSession session = sessions.get(sessionToken);
        if (session == null) {
            throw new SecurityException("Invalid session");
        }

        Path logDir = resolveAgentPath(session.tenantId, targetAgentId);
        if (!Files.exists(logDir)) {
            return Collections.emptyList();
        }

        List<String> results = new ArrayList<>();
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(logDir, "*.enc")) {
            for (Path entry : stream) {
                results.add(entry.getFileName().toString());
            }
        }
        return results;
    }

    private byte[] encryptData(byte[] key, byte[] data) throws Exception {
        SecretKeySpec keySpec = new SecretKeySpec(key, "AES");
        Cipher cipher = Cipher.getInstance(ALGORITHM);
        byte[] iv = new byte[16];
        new java.security.SecureRandom().nextBytes(iv);
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, new IvParameterSpec(iv));
        byte[] encrypted = cipher.doFinal(data);
        byte[] result = new byte[iv.length + encrypted.length];
        System.arraycopy(iv, 0, result, 0, iv.length);
        System.arraycopy(encrypted, 0, result, iv.length, encrypted.length);
        return result;
    }

    private byte[] decryptData(byte[] key, byte[] data) throws Exception {
        SecretKeySpec keySpec = new SecretKeySpec(key, "AES");
        Cipher cipher = Cipher.getInstance(ALGORITHM);
        byte[] iv = Arrays.copyOf(data, 16);
        byte[] encrypted = Arrays.copyOfRange(data, 16, data.length);
        cipher.init(Cipher.DECRYPT_MODE, keySpec, new IvParameterSpec(iv));
        return cipher.doFinal(encrypted);
    }
}
